def orbit(r,c):
 pts={(r,c)}
 changed=True
 while changed:
  old=len(pts)
  for a,b in list(pts):
   for p in [(b,a),(31-a,b),(a,31-b),(31-a,31-b)]:
    if 0<=p[0]<30 and 0<=p[1]<30: pts.add(p)
  changed=len(pts)>old
 return pts
